const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(o,selected)=>Object.entries(o).map(([v,l])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('');
let session=JSON.parse(sessionStorage.getItem(config.mode==='portal'?'vertice-green-portal-session':'vertice-session')||'null'), profile={},matters=[],matter=null,requirements=[],states=[],findings=[],documents=[],members=[],tab='requirements',filter='',search='';
let refreshing;
function saveSession(data){session=data;sessionStorage.setItem(config.mode==='portal'?'vertice-green-portal-session':'vertice-session',JSON.stringify(data));}
async function request(path,{method='GET',body,auth=true,raw=false}={}){
 if(auth&&config.mode==='local'&&session?.expires_at<Date.now()/1000+60){session=null;sessionStorage.removeItem(config.mode==='portal'?'vertice-green-portal-session':'vertice-session');login();throw new Error('Sessão local expirada. Entre novamente.');}
 if(auth&&config.mode==='portal'&&session?.expires_at<Date.now()/1000+60)await refreshPortalSession();
 if(auth&&config.mode!=='portal'&&session?.expires_at<Date.now()/1000+60){
  refreshing??=request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token},auth:false}).then(d=>saveSession({...d,expires_at:Date.now()/1000+d.expires_in})).finally(()=>refreshing=null);
  try{await refreshing;}catch(e){session=null;sessionStorage.removeItem(config.mode==='portal'?'vertice-green-portal-session':'vertice-session');login();throw e;}
 }
 const headers=(config.mode==='local'||config.mode==='portal')?{}:{apikey:config.key};
 if(auth&&session)headers.Authorization=`Bearer ${session.access_token}`;
 if(body&&!raw)headers['Content-Type']='application/json';
 const res=await fetch(config.url+path,{method,headers,credentials:config.mode==='portal'?'omit':'include',cache:'no-store',body:body?(raw?body:JSON.stringify(body)):undefined});
 let parsed=true;
 const data=await res.json().catch(()=>{parsed=false;return null;});
 if(!res.ok){
  const detail=data?.message||data?.msg||data?.error_description||(typeof data?.error==='string'?data.error:null);
  if(detail)throw new Error(detail);
  if(res.status===401||res.status===403)throw new Error(`A proteção de acesso recusou a solicitação (HTTP ${res.status}). Abra este endereço no Chrome ou Edge, valide o e-mail e tente novamente.`);
  throw new Error(`Falha na comunicação com o servidor (HTTP ${res.status||'desconhecido'}). Tente novamente ou informe este código.`);
 }
 if(!parsed)throw new Error('O acesso retornou uma página de validação em vez da resposta do módulo. Abra o endereço no Chrome ou Edge e valide o e-mail novamente.');
 return data;
}
const rpc=(fn,body={})=>request('/rest/v1/rpc/'+fn,{method:'POST',body});
const read=(table,query='')=>request('/rest/v1/'+table+'?select=*'+query);
function toast(text,error=false){document.querySelector('#notice')?.remove();const n=document.createElement('div');n.id='notice';n.className=error?'notice error':'notice';n.role='status';n.textContent=text;document.body.append(n);setTimeout(()=>n.remove(),6500);}
function bind(id,event,fn){document.getElementById(id)?.addEventListener(event,async e=>{const b=e.submitter||e.currentTarget;if(b.dataset.busy)return;try{b.dataset.busy='1';if(b.tagName==='BUTTON')b.disabled=true;await fn(e);}catch(err){const authMessage=document.querySelector('#auth-message');if(authMessage){authMessage.textContent=err.message;authMessage.setAttribute('role','alert');}toast(err.message,true);}finally{delete b.dataset.busy;if(b.tagName==='BUTTON')b.disabled=false;}});}
function login(){
 if(config.mode==='portal'){root.innerHTML='<div class="empty"><h2>Verificando acesso no portal Vértice…</h2><p>Use seu login e segundo fator do painel master.</p></div>';parent.postMessage({type:'green-request-session'},location.origin);return;}

 root.innerHTML=`<div class="login"><section class="intro"><a class="brand institutional-brand" href="#" aria-label="Vértice Educação Superior"><img class="institutional-logo" src="${brandLogo}" alt="Vértice Educação Superior" width="1703" height="390"></a><div><p class="eyebrow">AQUISIÇÕES DE IES</p><h1>Clareza para decidir.<br>Rigor para adquirir.</h1><p>Um ambiente reservado para conduzir a due diligence, organizar evidências e transformar riscos em decisões.</p></div><small>Mandatos segregados · Acesso por autorização</small></section><section class="login-form"><div class="form-wrap"><p class="eyebrow">AMBIENTE DE DUE DILIGENCE</p><h2>Acesse seu espaço</h2><p>Entre com a conta autorizada para seus mandatos.</p><form id="login"><label>E-mail<input name="email" type="email" autocomplete="username" required></label><label>Senha<input name="password" type="password" minlength="12" autocomplete="current-password" required></label><button class="primary" type="submit">Entrar no ambiente <span>→</span></button><button type="button" id="signup" class="text-btn">Criar conta de acesso</button></form><p class="fine">A criação de conta não concede acesso aos mandatos. Seu responsável precisa autorizar sua participação.</p><p id="auth-message" role="status"></p></div></section></div>`;
 if((config.mode==='local'||config.mode==='portal')){document.querySelector('.form-wrap>p.eyebrow').textContent='VÉRTICE AQUISIÇÕES · ACESSO RESERVADO';document.querySelector('.form-wrap h2').textContent='Crie sua senha para começar';document.querySelector('.form-wrap>p:not(.eyebrow)').textContent='Primeiro acesso: escolha uma senha com pelo menos 12 caracteres e clique em Criar minha senha e entrar. Se já cadastrou, use Entrar com minha senha.';const emailField=document.querySelector('[name=email]');emailField.value='vrcmeirelles@gmail.com';emailField.readOnly=true;const passwordField=document.querySelector('[name=password]');passwordField.placeholder='Pelo menos 12 caracteres';document.querySelector('.form-wrap>p.fine').textContent='Esta é a senha do módulo Vértice. Se você recebeu um link reservado de ativação, use-o para criar a senha uma única vez. Nos próximos acessos, entre com sua senha.';document.querySelector('#signup').textContent='Criar minha senha e entrar';document.querySelector('#signup').className='primary';document.querySelector('#login button[type=submit]').textContent='Entrar com minha senha';document.querySelector('#login button[type=submit]').className='secondary';}
 bind('login','submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const d=await request('/auth/v1/token?grant_type=password',{method:'POST',auth:false,body:{email:f.get('email'),password:f.get('password')}});saveSession({...d,expires_at:Date.now()/1000+d.expires_in});await home();});
 bind('signup','click',async()=>{const form=document.querySelector('#login');if(!form.reportValidity())return;const f=new FormData(form);const d=await request('/auth/v1/signup',{method:'POST',auth:false,body:{email:f.get('email'),password:f.get('password'),...((config.mode==='local'||config.mode==='portal')&&config.setupProtected?{activation_token:sessionStorage.getItem('vertice-activation')}: {})}});if(d.access_token){saveSession({...d,expires_at:Date.now()/1000+d.expires_in});await home();}else if(d.local_account_created){sessionStorage.removeItem('vertice-activation');const loginData=await request('/auth/v1/token?grant_type=password',{method:'POST',auth:false,body:{email:f.get('email'),password:f.get('password')}});saveSession({...loginData,expires_at:Date.now()/1000+loginData.expires_in});await home();}else document.querySelector('#auth-message').textContent='Confira seu e-mail para confirmar a conta. Depois, volte aqui para entrar.';});
}
function shell(content){root.innerHTML=`<aside><a class="brand institutional-brand" href="#" aria-label="Vértice Educação Superior"><img class="institutional-logo" src="${brandLogo}" alt="Vértice Educação Superior" width="1703" height="390"></a><p class="nav-label">ÁREA DE TRABALHO</p><button id="home" class="nav active">◈ <span>Aquisições</span></button><button id="model-library" class="nav model-nav">▤ <span>Modelos de documentos</span></button><button id="demo-opinion" class="nav model-nav">◇ <span>Teste com parecer</span></button><div class="aside-bottom"><span class="lock">◇</span><strong>Ambiente reservado</strong><p>O acesso é individual e limitado aos seus mandatos.</p></div></aside><main><header><div class="header-identity"><a class="header-brand" href="#" aria-label="Vértice Educação Superior"><img class="header-logo" src="${brandLogo}" alt="Vértice Educação Superior" width="1703" height="390"></a><span class="header-context">Aquisições ${matter?'<b>/</b> '+esc(matter.code):''}</span></div><div><span class="account">${esc(session?.user?.email)}</span>${config.mode==='portal'?'<a class="text-btn" href="/master" target="_top">← Painel master</a>':''}<button id="logout" class="text-btn">Sair ↗</button>${config.mode==='local'?'<button id="shutdown" class="text-btn">Encerrar módulo</button>':''}</div></header><div class="content">${content}</div></main>`;bind('shutdown','click',async()=>{await request('/local/shutdown',{method:'POST',body:{}});sessionStorage.removeItem(config.mode==='portal'?'vertice-green-portal-session':'vertice-session');session=null;root.innerHTML='<div class="empty"><h2>Módulo encerrado.</h2><p>Os dados foram salvos. Use Abrir-Aquisicoes para voltar.</p></div>';});bind('model-library','click',()=>showModels());bind('demo-opinion','click',showDemoOpinion);bind('home','click',home);bind('logout','click',async()=>{if(config.mode==='portal'){parent.postMessage({type:'green-logout'},location.origin);return;}try{await request('/auth/v1/logout',{method:'POST'});}finally{session=null;sessionStorage.removeItem(config.mode==='portal'?'vertice-green-portal-session':'vertice-session');matter=null;login();}});}
async function home(){matter=null;[profile,matters]=await Promise.all([rpc('dd_profile'),read('dd_matters','&order=created_at.desc')]);if(new URLSearchParams(location.hash.slice(1)).has('mandato')){const params=new URLSearchParams(location.hash.slice(1)),id=params.get('mandato');history.replaceState(null,'',location.pathname+location.search);if(matters.some(m=>m.id===id)){tab=['requirements','scope','review','ebitda','valuation','opinion','findings','documents','agent','members'].includes(params.get('aba'))?params.get('aba'):'requirements';await openMatter(id);}else{renderHome();toast('Mandato não encontrado ou sem autorização.',true);}}else if(['#teste-parecer','#teste-aca'].includes(location.hash)){const single=location.hash==='#teste-aca';history.replaceState(null,'',location.pathname+location.search);if(single)showSingleDemoOpinion();else await showDemoOpinion();}else renderHome();}
function renderHome(){
 shell(`<div class="page-heading"><div><p class="eyebrow">DUE DILIGENCE · ENSINO SUPERIOR</p><h1>Mandatos de aquisição</h1><p>Da primeira análise à decisão de investimento.</p></div>${profile.admin?'<button id="new-matter" class="primary">+ Novo mandato</button>':''}</div><div class="stats"><article><span>MEUS MANDATOS</span><strong>${matters.length.toString().padStart(2,'0')}</strong><small>Operações com acesso autorizado</small></article><article><span>EM ANDAMENTO</span><strong>${matters.filter(m=>['active','draft','closing'].includes(m.status)).length.toString().padStart(2,'0')}</strong><small>Triagem, análise e fechamento</small></article><article><span>INSTRUMENTO DE ANÁLISE</span><strong>305 <em>requisitos</em></strong><small>10 frentes de due diligence</small></article></div><div class="section-heading"><h2>Suas operações</h2><span class="muted">Acesso segregado por mandato</span></div><div class="matter-grid">${matters.map(m=>`<button class="matter-card" data-matter="${m.id}"><div><span class="tag">${esc(m.code)}</span><span class="status">${esc(({draft:'Em preparação',active:'Em análise',closing:'Fechamento',closed:'Encerrado',cancelled:'Cancelado'})[m.status])}</span></div><h2>${esc(m.title)}</h2><p>${esc(m.target_name)}</p><dl><div><dt>CLIENTE</dt><dd>${esc(m.client_name)}</dd></div><div><dt>POSIÇÃO</dt><dd>${m.side==='buyer'?'Comprador':m.side==='seller'?'Vendedor':'Neutro'}</dd></div></dl><footer>Abrir mandato <span>↗</span></footer></button>`).join('')||`<div class="empty"><div class="empty-icon">◇</div><h2>Seu próximo movimento começa aqui.</h2><p>${profile.admin?'Abra um mandato para iniciar a análise dos 305 requisitos.':'Você ainda não participa de um mandato. Solicite autorização ao responsável pela operação.'}</p></div>`}</div><div class="info-strip"><span>01 — 10</span><div><strong>Uma análise em todas as frentes.</strong><p>Regulatória, acadêmica, financeira, tributária, trabalhista e mais cinco áreas conectadas.</p></div></div>`);
 document.querySelectorAll('[data-matter]').forEach(b=>b.onclick=()=>openMatter(b.dataset.matter).catch(e=>toast(e.message,true)));
 bind('new-matter','click',()=>modal('Novo mandato',`<form id="create-matter">${config.mode==='portal'?`<label>Instituição contratante<select name="institution_id" required>${options(Object.fromEntries((profile.institutions||[]).map(i=>[i.id,i.name])))}</select></label>`:''}<label>Título da operação<input name="title" minlength="3" required placeholder="Aquisição · Instituição"></label><label>Instituição-alvo<input name="target" minlength="3" required></label><div class="form-grid"><label>Cliente<input name="client" minlength="3" required></label><label>Posição<select name="side">${options({buyer:'Comprador',seller:'Vendedor',neutral:'Neutro'})}</select></label></div><label>Raiz do CNPJ (8 dígitos)<input name="cnpj" pattern="[0-9]{8}" maxlength="8" inputmode="numeric"></label><details><summary>Alvo já atendido: equipe separada e parede</summary><label class="check"><input type="checkbox" name="separate_team"> Este alvo exige equipe separada.</label><label>Responsável da equipe separada (e-mail da conta confirmada)<input name="lead_email" type="email"></label><label>Referência da análise de conflito e dos consentimentos<input name="consent_ref"></label></details><label class="check"><input type="checkbox" name="conflict_checked" required> Realizei a checagem de conflitos e confirmei a ausência de impedimento.</label><p class="fine">O mandato será criado em preparação, com acesso do responsável válido por 180 dias. Alvos com mandato aberto exigem análise de conflito antes da abertura de outra operação.</p><button class="primary">Criar mandato</button></form>`,()=>bind('create-matter','submit',async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget));p.conflict_checked=true;const id=await rpc('dd_create_matter',{payload:p});closeModal();await openMatter(id);})));
}
function modal(title,body,setup){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button id="close-modal" aria-label="Fechar">×</button></div>${body}`;document.body.append(d);d.showModal();bind('close-modal','click',closeModal);setup?.();}
function closeModal(){document.querySelector('dialog')?.remove();}
let templateCatalog=null;
let agentReport=null,documentLinks=[],workflowData=null;
async function showModels(code=null){
 templateCatalog??=await request('/templates/catalogo');
 const models=templateCatalog.models.filter(m=>!code||(m.requirements.includes(code)&&m.requirements.length<305));
 if(code)models.sort((a,b)=>(a.requirements.length===305)-(b.requirements.length===305));
 modal(code?'Modelos para '+code:'Modelos de documentos',`<p>Baixe, preencha no Word e envie o arquivo preenchido ao cofre do mandato. Os modelos organizam o levantamento; documentos oficiais e contratos existentes devem ser obtidos separadamente.</p>${code?'':'<button id="download-library" class="secondary">Baixar biblioteca completa em ZIP ↓</button>'}<div class="template-list">${models.map(m=>`<article class="template-item"><div><span class="tag">${esc(m.id)} · Word</span><h3>${esc(m.title)}</h3><p>${esc(m.purpose)}</p><small>${esc(m.limitation)}</small></div><button class="secondary" data-template="${m.id}">Baixar Word ↓</button></article>`).join('')}</div>`);
 document.querySelectorAll('[data-template]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const m=models.find(m=>m.id===b.dataset.template);await downloadModel('/templates/'+m.id+'.docx',m.id+' - '+m.title+'.docx');}catch(e){toast(e.message,true);}finally{b.disabled=false;}});
 bind('download-library','click',()=>downloadModel('/templates/biblioteca.zip','Vertice-fichas-para-preencher-v2.zip'));
}
async function downloadModel(path,filename){
 const res=await fetch(config.url+path,{headers:{Authorization:'Bearer '+session.access_token},credentials:config.mode==='portal'?'omit':'include',cache:'no-store'});
 if(!res.ok){const error=await res.json().catch(()=>null);throw new Error(error?.message||'Não foi possível baixar o modelo. Entre novamente e tente outra vez.');}
 const data=await res.blob();if(!data.size)throw new Error('O arquivo do modelo está vazio.');
 const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
async function openMatter(id){
 agentReport=null;
 matter=matters.find(m=>m.id===id);if(!matter)throw new Error('Mandato não encontrado.');
 [requirements,states,findings,documents,members]=await Promise.all([read('dd_requirements','&order=code'),read('dd_requirement_state',`&matter_id=eq.${id}`),read('dd_findings',`&matter_id=eq.${id}&order=created_at.desc`),read('dd_documents',`&matter_id=eq.${id}&order=created_at.desc`),read('dd_matter_members',`&matter_id=eq.${id}`)]);
 documentLinks=(config.mode==='local'||config.mode==='portal')?await read('dd_document_links',`&matter_id=eq.${id}`):[];
 workflowData=(config.mode==='local'||config.mode==='portal')?await request('/workflow/'+id):null;
 if(workflowData){requirements=workflowData.requirements;states=workflowData.states;documents=workflowData.documents;documentLinks=workflowData.links;}
 renderMatter();
}
function writable(){return members.some(m=>m.user_id===session.user.id&&['matter_lead','analyst'].includes(m.role)&&!m.revoked_at&&new Date(m.expires_at)>new Date());}
function renderMatter(){
 const done=workflowData?states.length-workflowData.counts.pending:states.filter(s=>s.status==='compliant').length,pct=states.length?Math.round(done/states.length*100):0;
 shell(`<button id="back" class="text-btn">← Todos os mandatos</button><div class="page-heading detail-heading"><div><p class="eyebrow">${esc(matter.code)} · ${matter.side==='buyer'?'COMPRADOR':'VENDEDOR'}</p><h1>${esc(matter.title)}</h1><p>${esc(matter.target_name)} · ${esc(matter.client_name)}</p></div><button id="export" class="secondary">Exportar tracker ↓</button></div>${matter.scope_note==='SEED-TESTE-FLUXO-COMPLETO-V1'?'<div class="form-guide"><strong>MANDATO DE TESTE — TODOS OS DADOS SÃO FICTÍCIOS.</strong><p>Respostas, evidências e revisões foram preparadas por automação para este exercício. Não representam sua revisão pessoal. O parecer aguarda sua leitura e aprovação; não avalia uma aquisição real.</p></div>':''}<div class="stats"><article><span>ANÁLISES ATUAIS</span><strong>${done} <em>/ ${states.length}</em></strong><div class="progress"><i style="width:${pct}%"></i></div></article><article><span>ACHADOS REGISTRADOS</span><strong>${workflowData?workflowData.events.length:findings.length} <em>eventos distintos</em></strong><small>${workflowData?workflowData.events.filter(e=>e.body.risk==='red'&&!e.body.resolved).length:findings.filter(f=>f.severity==='red').length} de severidade alta</small></article><article><span>DOCUMENTOS NO COFRE</span><strong>${documents.length.toString().padStart(2,'0')}</strong><small>Arquivos privados deste mandato</small></article></div><nav class="tabs">${optionsTabs()}</nav><section id="tab-content"></section>`);
 bind('back','click',home);bind('export','click',exportTracker);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderMatter();});renderTab();
}
function optionsTabs(){return Object.entries({requirements:'Preenchimento',...(config.mode==='portal'?{base:'Base da operação',emec:'e-MEC · Regulação'}:{}),...(workflowData?{scope:'Escopo e conferências',review:'Análise das evidências',ebitda:'Calcular EBITDA',valuation:'Preço da aquisição',opinion:'Parecer e aprovação'}:{}),findings:'Riscos e providências',documents:'Cofre documental',...((config.mode==='local'||config.mode==='portal')?{agent:'Conferência local'}:{}),members:'Equipe'}).map(([v,l])=>`<button data-tab="${v}" class="${tab===v?'selected':''}">${l}</button>`).join('');}
function renderTab(){
 const el=document.querySelector('#tab-content');
 if(config.mode==='portal'&&tab==='base'){operationForms.baseView(el).catch(e=>toast(e.message,true));return;}
 if(workflowData&&tab==='ebitda'){renderEbitda(el);return;}
 if(workflowData&&tab==='valuation'){renderValuation(el);return;}
 if(workflowData&&tab==='emec'){renderRegulatory(el);return;}
 if(workflowData&&['scope','review','opinion'].includes(tab)){renderWorkflowTab(el);return;}
 if(workflowData&&tab==='findings'){renderWorkflowEvents(el);return;}
 if(tab==='requirements'){
 el.innerHTML=`${(config.mode==='local'||config.mode==='portal')?'<div class="form-guide"><strong>Preencha cada requisito no próprio site.</strong><p>Clique em Preencher / anexar, preencha o formulário e consulte a Base da operação. Anexe os comprovantes e documentos complementares necessários. O vínculo será feito automaticamente.</p></div>':''}<div class="toolbar"><input id="search" type="search" placeholder="Buscar requisito, código ou documento…" value="${esc(search)}" aria-label="Buscar requisito"><select id="front" aria-label="Frente">${options({'':'Todas as frentes',...fronts},filter)}</select></div><div id="requirement-list"></div>`;
 const list=()=>{const st=new Map(states.map(s=>[s.requirement_id,s]));const rows=requirements.filter(r=>st.has(r.id)&&(!filter||r.front===filter)&&(!search||`${r.code} ${fronts[r.front]||r.front} ${r.subfront||''} ${r.question} ${r.expected_doc}`.toLowerCase().includes(search.toLowerCase())));document.querySelector('#requirement-list').innerHTML=rows.map(r=>{const s=st.get(r.id);return `<article class="requirement"><div class="req-code"><button type="button" class="tag requirement-help" data-help="${r.id}" aria-label="Entender o requisito ${esc(r.code)}" aria-haspopup="dialog" title="${esc(r.code+' — '+(fronts[r.front]||r.front)+': '+r.question+' Documento esperado: '+r.expected_doc)}">${esc(r.code)} <span aria-hidden="true">ⓘ</span></button><span class="req-caption"><strong>${esc(fronts[r.front]||r.front)}</strong><span>${esc(r.subfront||'Análise da frente')}</span></span>${config.mode!=='local'?`<button type="button" class="template-link" data-models="${esc(r.code)}">Modelos para preencher ↓</button>`:''}<span class="critical ${r.criticality}">${esc({critical:'Crítico',high:'Alta atenção',normal:'Normal',low:'Baixa'}[r.criticality])}</span></div><div><h3>${esc(r.question)}</h3><p>${esc(r.expected_doc)}</p>${workflowData?.form_answers?.some(f=>f.state_id===s.id)?'<small class="native-form-badge">Formulário estruturado preenchido · sujeito à revisão</small>':''}${s.answer?`<p class="response-preview"><strong>Resposta:</strong> ${esc(s.answer.slice(0,220))}${s.answer.length>220?'…':''}</p>`:''}${(config.mode==='local'||config.mode==='portal')?`<small>${documentLinks.filter(l=>l.state_id===s.id).length} anexo(s) vinculado(s) · ${esc(reviewLabel(s.id))}</small>`:''}${s.note?`<small class="note">${esc(s.note)}</small>`:''}</div><div class="req-actions">${(config.mode==='local'||config.mode==='portal')?`<button class="primary" data-response="${r.id}">${writable()?(s.answer?'Editar resposta / anexos':'Preencher / anexar'):'Ver resposta / anexos'}</button>`:''}<button class="state-btn" data-state="${s.id}">${esc(workflowData&&['compliant','not_applicable'].includes(s.status)?'Situação anterior — revisar':statuses[s.status])} ${writable()?'↗':''}</button></div></article>`;}).join('')||'<div class="empty">Nenhum requisito para este filtro.</div>';document.querySelectorAll('[data-response]').forEach(b=>b.onclick=()=>responseForm(b.dataset.response).catch(e=>toast(e.message,true)));document.querySelectorAll('[data-models]').forEach(b=>b.onclick=()=>showModels(b.dataset.models).catch(e=>toast(e.message,true)));document.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>{const r=requirements.find(r=>r.id===b.dataset.help);modal('Entenda o requisito '+r.code,`<p class="eyebrow">${esc(fronts[r.front]||r.front)} · ${esc(r.subfront)}</p><h3>O que verificar</h3><p>${esc(r.question)}</p><h3>Documentos esperados</h3><p>${esc(r.expected_doc)}</p><h3>Como usar este requisito</h3><p>Solicite os documentos indicados, confira se respondem à questão e atualize a situação do item. Registre observações na nota; se identificar um risco, registre um achado vinculado a este requisito.</p>`);});document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{if(!writable())return;const s=states.find(s=>s.id===b.dataset.state),r=requirements.find(r=>r.id===s.requirement_id);modal(r.code+' · Atualizar requisito',`<p>${esc(r.question)}</p><form id="state-form"><label>Situação<select name="status">${options(Object.fromEntries(Object.entries(statuses).filter(([k])=>!['compliant','not_applicable'].includes(k))),s.status)}</select></label><label>Nota / justificativa<textarea name="note" maxlength="10000">${esc(s.note)}</textarea></label><button class="primary">Salvar atualização</button></form>`,()=>bind('state-form','submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await rpc('dd_save_state',{m:matter.id,r:r.id,s:f.get('status'),n:f.get('note')});closeModal();await openMatter(matter.id);toast('Requisito atualizado.');}));});};
 document.querySelector('#search').oninput=e=>{search=e.target.value;list();};document.querySelector('#front').onchange=e=>{filter=e.target.value;list();};list();
 }else if(tab==='findings'){
 el.innerHTML=`<div class="section-heading"><h2>Riscos e mecanismos de proteção</h2>${writable()?'<button id="new-finding" class="primary">+ Registrar achado</button>':''}</div>${findings.map(f=>`<article class="finding"><div class="severity ${f.severity}">${esc({red:'Alta',amber:'Média',green:'Baixa'}[f.severity])}</div><div><span class="muted">${esc(f.code)} · ${esc(fronts[f.front])}</span><h3>${esc(f.title)}</h3><p>${esc(f.description)}</p><p><strong>Consequência:</strong> ${esc(f.consequence)}</p><span class="tag">${esc(mechanisms[f.mechanism])}</span></div><strong>${f.value_unquantified?'Não quantificado':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(f.value_brl)}</strong></article>`).join('')||'<div class="empty"><h2>Nenhum achado registrado.</h2><p>Registre os riscos identificados durante a análise.</p></div>'}`;
 bind('new-finding','click',()=>modal('Registrar achado',`<form id="finding-form"><label>Requisito<select name="requirement_id">${requirements.filter(r=>states.some(s=>s.requirement_id===r.id)).map(r=>`<option value="${r.id}">${esc(r.code+' · '+r.question)}</option>`).join('')}</select></label><label>Título<input name="title" minlength="3" maxlength="300" required></label><label>Descrição<textarea name="description" minlength="10" required></textarea></label><label>Consequência para a operação<textarea name="consequence" minlength="20" required></textarea></label><div class="form-grid"><label>Severidade<select name="severity">${options({red:'Alta',amber:'Média',green:'Baixa'})}</select></label><label>Valor em risco (R$)<input name="value" type="number" min="0.01" step="0.01" placeholder="Deixe vazio se não quantificado"></label></div><label>Mecanismo de proteção<select name="mechanism">${options(mechanisms)}</select></label><button class="primary">Registrar achado</button></form>`,()=>bind('finding-form','submit',async e=>{e.preventDefault();await rpc('dd_add_finding',{m:matter.id,payload:Object.fromEntries(new FormData(e.currentTarget))});closeModal();await openMatter(matter.id);}))); 
 }else if(tab==='documents'){
 el.innerHTML=`<div class="section-heading"><h2>Acervo privado</h2>${writable()?'<button id="upload" class="primary">↑ Adicionar documento</button>':''}</div><p class="fine">PDF, planilhas, Word, CSV e imagens · Até 15 MB por arquivo. A verificação antivírus automática ainda não está disponível; valide os arquivos antes de abri-los.</p>${documents.map(d=>`<article class="document"><span class="doc-icon">▤</span><div><h3>${esc(d.file_name)}</h3><p>${(d.size_bytes/1024/1024).toFixed(2)} MB · ${esc(d.classification==='privileged'?'Privilegiado':'Restrito')} · ${new Date(d.created_at).toLocaleDateString('pt-BR')}</p></div><button class="secondary" data-download="${d.id}">Baixar ↓</button></article>`).join('')||'<div class="empty"><h2>O cofre está vazio.</h2><p>Organize as evidências desta operação em um único lugar.</p></div>'}`;
 bind('upload','click',()=>modal('Adicionar documento',`<form id="upload-form"><label>Arquivo<input name="file" type="file" accept=".pdf,.xlsx,.docx,.csv,.png,.jpg,.jpeg" required></label><label>Classificação<select name="classification">${options({restricted:'Restrito ao mandato',privileged:'Privilegiado · somente responsável'})}</select></label><p class="fine">Envie apenas documentos necessários para este mandato.</p><button class="primary">Enviar para o cofre</button></form>`,()=>bind('upload-form','submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget),file=form.get('file');if(file.size===0||file.size>15728640)throw new Error('O arquivo deve ter entre 1 byte e 15 MB.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))).map(b=>b.toString(16).padStart(2,'0')).join('');if(documents.some(d=>d.sha256===hash))throw new Error('Este arquivo já existe neste mandato.');const path=`${matter.id}/${crypto.randomUUID()}/${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;await request('/storage/v1/object/dd-acervo/'+path+'?front='+encodeURIComponent(front)+'&classification='+encodeURIComponent(classification),{method:'POST',body:file,raw:true});await rpc('dd_register_document',{m:matter.id,payload:{path,front,classification,name:file.name,mime:file.type||'application/octet-stream',size:file.size,sha256:hash,classification:form.get('classification')}});closeModal();await openMatter(matter.id);toast('Documento registrado no cofre.');})));
 document.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const path=await rpc('dd_log_download',{d:b.dataset.download});const d=await request('/storage/v1/object/sign/dd-acervo/'+path,{method:'POST',body:{expiresIn:300}});const a=document.createElement('a');a.href=d.absolute?d.signedURL:config.url+'/storage/v1'+d.signedURL;a.target='_blank';a.rel='noopener noreferrer';a.click();}catch(e){toast(e.message,true);}finally{b.disabled=false;}});
 }else if(tab==='agent'){
 renderAgent(el);
 }else{
 const lead=members.some(m=>m.user_id===session.user.id&&m.role==='matter_lead'&&!m.revoked_at&&new Date(m.expires_at)>new Date());
 el.innerHTML=`<div class="section-heading"><h2>Participantes autorizados</h2>${lead&&config.mode!=='local'?'<button id="add-member" class="primary">+ Autorizar participante</button>':''}</div>${members.map(m=>`<article class="document"><span class="doc-icon">◇</span><div><h3>${m.user_id===session.user.id?esc(session.user.email):esc(m.user_id)}</h3><p>${esc({matter_lead:'Responsável',analyst:'Analista',reviewer:'Revisor',client_observer:'Observador'}[m.role]||m.role)} · Até ${new Date(m.expires_at).toLocaleDateString('pt-BR')} ${m.revoked_at?'· Revogado':''}</p></div></article>`).join('')}`;
 bind('add-member','click',()=>modal('Autorizar participante',`<form id="member-form"><label>E-mail da conta já confirmada<input type="email" name="email_address" required></label><label>Papel<select name="member_role">${options({analyst:'Analista · leitura e edição',reviewer:'Revisor · leitura',client_observer:'Observador · leitura'})}</select></label><label>Acesso válido até<input type="date" name="expiry" min="${new Date(Date.now()+86400000).toISOString().slice(0,10)}" max="${new Date(Date.now()+179*86400000).toISOString().slice(0,10)}" required></label><button class="primary">Autorizar acesso</button></form>`,()=>bind('member-form','submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));await rpc('dd_add_member',{m:matter.id,...f,expiry:new Date(f.expiry+'T23:59:00-03:00').toISOString()});closeModal();await openMatter(matter.id);}))); 
 }
}
function exportTracker(){const st=new Map(states.map(s=>[s.requirement_id,s]));const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const lines=[['Código','Frente','Requisito','Documento esperado','Situação','Nota','Resposta','Evidências vinculadas'],...requirements.filter(r=>st.has(r.id)).map(r=>[r.code,fronts[r.front],r.question,r.expected_doc,statuses[st.get(r.id).status],st.get(r.id).note,st.get(r.id).answer,documentLinks.filter(l=>l.state_id===st.get(r.id).id).map(l=>documents.find(d=>d.id===l.document_id)?.file_name).filter(Boolean).join(' | ')])];const blob=new Blob(['\ufeff'+lines.map(l=>l.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=matter.code+'-tracker.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const reviewLabels={pending:'Ainda não verificado',verified:'Conforme após revisão',qualified:'Com ressalva',noncompliant:'Não conforme',not_applicable:'Não aplicável',not_verified:'Não verificado — limitação registrada'};
function reviewLabel(stateId){const e=workflowData?.effective.find(e=>e.state_id===stateId);return reviewLabels[e?.valid?e.review.body.decision:'pending'];}
async function workflowSave(action,payload){const id=matter.id;await request('/workflow/'+id+'/'+action,{method:'POST',body:payload});closeModal();await openMatter(id);toast('Registro salvo. Alterações relevantes exigem nova revisão ou aprovação.');}
function renderWorkflowTab(el){
 const w=workflowData;
 if(tab==='scope'){
  const p=w.profile?.body||{};
  el.innerHTML=`<h2>Defina o que será analisado</h2><p>O escopo orienta a aplicação das perguntas. Nenhum item será marcado automaticamente como não aplicável.</p>${!w.lead?'<p>O responsável pelo mandato define e aprova este escopo.</p>':''}<form id="scope-form"><div class="form-grid"><label>Entidades, unidades e cursos incluídos<textarea name="entities" required>${esc(p.entities)}</textarea></label><label>Como será feita a compra?<input name="transaction_type" value="${esc(p.transaction_type)}" placeholder="Ex.: compra de quotas ou compra de ativos" required></label></div><div class="form-grid"><label>O que está incluído?<textarea name="included" required>${esc(p.included)}</textarea></label><label>O que está excluído?<textarea name="excluded" required>${esc(p.excluded)}</textarea></label></div><div class="form-grid"><label>Data-base<input type="date" name="reference_date" value="${esc(p.reference_date)}" required></label><label>Tipo de instituição<input name="institution_type" value="${esc(p.institution_type)}" placeholder="Faculdade, centro universitário ou universidade" required></label></div><div class="form-grid"><label>Sistema de ensino e local<input name="education_system" value="${esc(p.education_system)}" placeholder="Federal/estadual e unidades federativas" required></label><label>Formatos de oferta<input name="modalities" value="${esc(p.modalities)}" placeholder="Presencial, semipresencial, a distância" required></label></div><label>Regime tributário e benefícios invocados<input name="tax_regime" value="${esc(p.tax_regime)}" placeholder="Informe também imunidade ou CEBAS, se houver" required></label><div class="form-grid"><label>Referência financeira de relevância (R$, opcional)<input name="materiality" type="number" min="0" step="0.01" value="${esc(p.materiality)}"></label><label>Critérios de atenção, inclusive sem valor<textarea name="materiality_reason" minlength="20" required placeholder="Considere continuidade, segurança, alunos, prazos e impacto; o valor não decide o risco sozinho.">${esc(p.materiality_reason)}</textarea></label></div><h2>Conferências entre frentes</h2><p>Registre os valores e as fontes. Cada arquivo deve estar vinculado ao requisito correspondente e conferido como suficiente. Uma igualdade numérica não confirma regularidade; diferenças precisam de explicação.</p>${w.comparisons.map(c=>`<fieldset class="evidence-fields" data-comparison="${c.id}"><legend>${esc(c.label)}</legend><p class="fine">${esc(c.left_code)} × ${esc(c.right_code)} · Situação: ${esc({pending:'Pendente',consistent:'Valores comparados',difference_explained:'Diferença registrada para revisão',not_applicable:'Não aplicável, com justificativa'}[c.result])}</p><div class="form-grid"><label>Valor/quantidade da primeira fonte<input data-key="left" type="number" min="0" step="0.01" value="${esc(c.left??'')}"></label><label>Valor/quantidade da segunda fonte<input data-key="right" type="number" min="0" step="0.01" value="${esc(c.right??'')}"></label></div><div class="form-grid"><label>Arquivo da primeira fonte<select data-key="left_document">${documentOptions(c.left_document)}</select></label><label>Arquivo da segunda fonte<select data-key="right_document">${documentOptions(c.right_document)}</select></label></div><label>Explicação, páginas/abas e providência<textarea data-key="note">${esc(c.note)}</textarea></label><label>Aplicação<select data-key="decision">${options({compared:'Conferência aplicável',not_applicable:'Não aplicável: justificar acima'},c.decision)}</select></label><label class="check"><input type="checkbox" data-key="reviewed" ${c.reviewed?'checked':''}> Conferi as fontes e registrei a explicação.</label></fieldset>`).join('')}${w.lead?'<button class="primary">Salvar escopo e conferências</button>':''}</form>`;
  if(!w.lead)el.querySelectorAll('input,textarea,select').forEach(e=>e.disabled=true);
  bind('scope-form','submit',async e=>{e.preventDefault();if(!w.lead)return;const data=Object.fromEntries(new FormData(e.currentTarget));data.comparisons=Array.from(el.querySelectorAll('[data-comparison]')).map(f=>Object.fromEntries([['id',f.dataset.comparison],...Array.from(f.querySelectorAll('[data-key]')).map(i=>[i.dataset.key,i.type==='checkbox'?i.checked:i.value])]));await workflowSave('profile',data);});
 }else if(tab==='review'){
  el.innerHTML=`<h2>Analise o que foi comprovado</h2><p>As respostas do vendedor permanecem separadas da avaliação. Cada conclusão registra o critério utilizado, as evidências examinadas e suas limitações.</p><p><strong>Conformes:</strong> ${w.counts.verified} · <strong>Com ressalva:</strong> ${w.counts.qualified} · <strong>Não conformes:</strong> ${w.counts.noncompliant} · <strong>Não aplicáveis:</strong> ${w.counts.not_applicable} · <strong>Não verificados:</strong> ${w.counts.not_verified} · <strong>Pendentes:</strong> ${w.counts.pending}</p><p class="fine">Instrumento ${esc(w.revision.version)}. ${esc(w.revision.purpose)}</p><div class="toolbar"><input id="review-search" type="search" placeholder="Buscar código ou pergunta"><select id="review-front">${options({'':'Todas as frentes',...fronts})}</select></div><div id="review-list"></div>`;
  const list=()=>{const search=document.querySelector('#review-search').value.toLowerCase(),front=document.querySelector('#review-front').value;document.querySelector('#review-list').innerHTML=requirements.filter(r=>(!front||r.front===front)&&(`${r.code} ${r.question}`.toLowerCase().includes(search))).map(r=>{const s=states.find(s=>s.requirement_id===r.id);return `<article class="document"><span class="tag">${esc(r.code)}</span><div><h3>${esc(r.question)}</h3><p>${esc(reviewLabel(s.id))}</p></div><button class="secondary" data-review="${s.id}">Abrir análise</button></article>`;}).join('');document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewForm(b.dataset.review));};document.querySelector('#review-search').oninput=list;document.querySelector('#review-front').onchange=list;list();
 }else if(tab==='opinion'){
  if(!w.lead){el.innerHTML='<p>O parecer e a aprovação são restritos ao responsável pelo mandato, pois podem conter evidências privilegiadas.</p>';return;}
  el.innerHTML=`<h2>Parecer vinculado à análise e às evidências</h2><p>O responsável escreve a recomendação e aprova uma versão identificada. Alterações posteriores na base exigem nova versão. A aprovação interna não é uma assinatura digital qualificada.</p><div class="form-guide"><strong>${w.readiness.length?'Ainda há condições para a aprovação final':'Análises atuais disponíveis para aprovação do responsável'}</strong><details><summary>Ver verificações (${w.readiness.length})</summary><ul>${w.readiness.map(i=>`<li>${esc(i)}</li>`).join('')||'<li>Não há bloqueios documentais automáticos; a decisão continua sendo do responsável.</li>'}</ul></details></div><div class="form-guide"><strong>Preço e condições de fechamento</strong><p>${esc(w.valuation?.result.conclusion||'Compatibilidade do preço ainda não analisada.')}</p><details><summary>Condições econômicas e impedimentos (${w.closing_readiness?.length||0})</summary><ul>${(w.closing_readiness||[]).map(i=>`<li>${esc(i)}</li>`).join('')}</ul><p>Aprovar o parecer não libera a compra nem pagamentos.</p></details></div><div class="toolbar"><button id="opinion-prepare" class="primary">Preparar nova versão do parecer</button><button id="workflow-history" class="secondary">Baixar histórico de alterações ↓</button></div>${w.opinions.map(o=>`<article class="document"><div><h3>${o.approval?'Aprovado pelo responsável':'Rascunho para revisão'} ${o.current?'· base atual':'· versão anterior, base alterada'}</h3><p>${new Date(o.created_at).toLocaleString('pt-BR')} · ${esc(o.approval?.body.name||'Aguardando aprovação')}</p><small>Versão ${esc(o.id)} · Hash ${esc(o.report_hash)}</small></div><button class="secondary" data-opinion-view="${o.id}">Abrir parecer</button>${!o.approval&&o.current&&!w.readiness.length?`<button class="primary" data-opinion-approve="${o.id}">Revisar e aprovar</button>`:''}</article>`).join('')||'<p>Nenhuma versão preparada. Você pode gerar um rascunho para visualizar o que ainda falta.</p>'}`;
  bind('opinion-prepare','click',()=>modal('Recomendação do responsável',`<form id="opinion-form"><label>Nome do responsável<input name="author" minlength="5" required></label><label>Identificação profissional ou função<input name="registration" minlength="3" required></label><label>Recomendação<select name="recommendation">${options({caution:'Cautela na aquisição',more_information:'Aguardar informações adicionais',do_not_proceed:'Não prosseguir',proceed:'Prosseguir nas condições descritas'})}</select></label><label>Fundamentos da conclusão<textarea name="narrative" rows="7" minlength="80" required placeholder="Explique por que prosseguir ou não; indique os códigos e eventos decisivos, as limitações e o impacto para o comprador."></textarea></label><label>Condições para fechar e riscos que permanecem<textarea name="conditions" rows="6" minlength="30" required placeholder="O que bloqueia o fechamento? O que altera o preço? Que proteção será negociada? Quem assume cada risco?"></textarea></label><button class="primary">Preparar rascunho com a base atual</button></form>`,()=>bind('opinion-form','submit',async e=>{e.preventDefault();await workflowSave('draft',Object.fromEntries(new FormData(e.currentTarget)));})));
  bind('workflow-history','click',async()=>downloadReport(JSON.stringify(await request('/workflow/'+matter.id+'/history'),null,2),'application/json',matter.code+'-historico.json'));
  document.querySelectorAll('[data-opinion-view]').forEach(b=>b.onclick=()=>opinionView(b.dataset.opinionView).catch(e=>toast(e.message,true)));
  document.querySelectorAll('[data-opinion-approve]').forEach(b=>b.onclick=()=>approvalForm(b.dataset.opinionApprove));
 }
}
function documentOptions(selected){return '<option value="">Selecione o arquivo</option>'+documents.map(d=>`<option value="${d.id}" ${d.id===selected?'selected':''}>${esc(d.file_name)}</option>`).join('');}
function renderEbitda(el){
 const w=workflowData,c=w.ebitda,b=c?.body||{},money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),percent=n=>n===null?'Não calculável':n.toLocaleString('pt-BR')+'%';
 if(!w.lead){el.innerHTML='<p>A calculadora e a DRE são acessíveis ao responsável pelo mandato.</p>';return;}
 const field=(key,label,help='',signed=false,value=b[key])=>`<label>${esc(label)} (R$)<input name="${key}" type="number" step="0.01" ${signed?'':'min="0"'} value="${esc(value??'')}" required><small class="fine">${esc(help)}</small></label>`;
 el.innerHTML=`<h2>Calcule o EBITDA da instituição</h2><div class="form-guide"><strong>O que é EBITDA?</strong><p>Também chamado de LAJIDA, é o resultado antes dos juros, dos tributos sobre o lucro, da depreciação e da amortização. Ajuda a comparar o desempenho econômico da instituição. Ele não é o dinheiro disponível no banco nem o preço de venda.</p><p><b>Como calculamos:</b> lucro ou prejuízo líquido + IRPJ e CSLL + despesas financeiras − receitas financeiras + depreciação + amortização + exaustão, se houver.</p><p>Copie os números da DRE do mesmo período. Use zero quando a conta não existir. A DRE é a Demonstração do Resultado do Exercício: o relatório contábil de receitas, despesas e resultado.</p></div><form id="ebitda-form"><fieldset class="evidence-fields"><legend>1. Qual instituição e período?</legend><label>Instituição, unidade ou conjunto de cursos<input name="scope" value="${esc(b.scope)}" required placeholder="Ex.: mantenedora e faculdade, incluindo a sede e a unidade B"></label><div class="form-grid"><label>Início do período<input type="date" name="start" value="${esc(b.start)}" required></label><label>Fim do período<input type="date" name="end" value="${esc(b.end)}" required></label><label>Os números são realizados ou previstos?<select name="basis">${options({historical:'Realizados, conforme DRE',projection:'Projeção: ainda não realizada'},b.basis||'historical')}</select></label></div></fieldset><fieldset class="evidence-fields"><legend>2. Copie estes valores da DRE</legend><div class="form-grid">${ebitdaFields.map(([key,label,help,signed])=>field(key,label,help,signed)).join('')}</div><label>Como os aluguéis e arrendamentos aparecem na contabilidade?<select name="lease_basis">${options({unknown:'Ainda não sei — confirmar com o contador',expense:'Aluguel reconhecido como despesa operacional',ifrs16:'CPC 06 / IFRS 16: depreciação do direito de uso e juros'},b.lease_basis||'unknown')}</select></label><p class="fine">O tratamento dos imóveis pode mudar a comparação do EBITDA. Não acrescente aluguel ao resultado nem subtraia parcelas de arrendamento por conta própria.</p></fieldset>
 <label class="check"><input name="education_enabled" type="checkbox" ${b.education_enabled?'checked':''}> Quero detalhar as receitas e os custos da instituição de ensino (opcional).</label><div id="education-detail" ${b.education_enabled?'':'hidden'}><div class="simple-help"><p>Este detalhamento ajuda o reitor a entender o resultado e confere se ele fecha com a DRE. Preencha cada conta uma única vez, pelo regime de competência. FIES é forma de financiamento das mensalidades, não uma receita extra a somar novamente. Não desconte duas vezes bolsas, cancelamentos ou perdas.</p><p>Informe somente despesas reconhecidas no período: compra de equipamentos não entra integralmente como despesa; depreciação e amortização já estão no cálculo pela DRE. Não acrescente benefícios tributários presumidos.</p></div>${educationGroups.map(g=>`<fieldset class="evidence-fields"><legend>${esc(g.title)}</legend><div class="form-grid">${g.keys.map(([key,label])=>field('edu_'+key,label,'Informe zero se não houver.',false,b.education?.[key])).join('')}</div></fieldset>`).join('')}<fieldset class="evidence-fields"><legend>Outros resultados e conferência</legend>${field('edu_other_result','Outros resultados reconhecidos, positivos ou negativos','Inclua itens necessários para fechar com a DRE, inclusive resultados não recorrentes. Não os exclua automaticamente.',true,b.education?.other_result)}<label>Como conferiu as contas e os rateios?<textarea name="edu_reconciliation" minlength="15" required placeholder="Explique contas incluídas, despesas compartilhadas entre unidades/cursos e diferenças para a DRE.">${esc(b.education?.reconciliation)}</textarea></label></fieldset></div><label>Média de alunos ativos no período (opcional)<input name="average_students" type="number" min="0.01" step="0.01" value="${esc(b.average_students??'')}" placeholder="Média de alunos, não apenas o total de matrículas no fim do ano"></label>
 <div id="ebitda-preview" class="form-guide" role="status" aria-live="polite"></div><fieldset class="evidence-fields"><legend>3. Anexe a DRE como evidência</legend><p>A DRE ficará no cofre privado e vinculada ao requisito FIN-01. Anexar não confirma a autenticidade ou a correção dos valores: a conferência permanece no fluxo de evidências.</p><label>Enviar a DRE<input name="dre_file" type="file" accept=".pdf,.xlsx,.docx,.csv,.png,.jpg,.jpeg"></label><label>Ou usar uma DRE já enviada<select name="evidence_document_id">${documentOptions(b.evidence_document_id)}</select></label><label>Página ou aba com os valores<input name="evidence_location" value="${esc(b.evidence_location)}" required placeholder="Ex.: DRE 2025, aba Resultado, linhas 10 a 35"></label>${c?.evidence?`<p>DRE salva: <b>${esc(c.evidence.file_name)}</b></p><button id="ebitda-dre-download" type="button" class="secondary">Baixar DRE salva</button>`:''}<label>Observações para o contador e para a análise<textarea name="note">${esc(b.note)}</textarea></label></fieldset><button class="primary" id="ebitda-save">Salvar cálculo e DRE</button><p class="fine">Os cálculos aparecem enquanto você preenche. Salvar não aprova o EBITDA, as evidências ou a aquisição. Não há extração automática dos números do anexo nem IA paga.</p></form>${c?'<div class="toolbar"><button id="ebitda-memory" class="secondary">Baixar memória de cálculo</button><button id="ebitda-to-price" class="secondary">Ir para a análise do preço</button></div>':''}<details class="simple-help"><summary>Referências e uso na gestão</summary><p>A fórmula segue a referência de conciliação da <a href="https://conteudo.cvm.gov.br/export/sites/cvm/legislacao/resolucoes/anexos/100/resol156.pdf" target="_blank" rel="noopener noreferrer">Resolução CVM 156</a>, aplicável à divulgação pelas companhias abertas. Aqui ela é usada como referência metodológica; não certifica as contas de uma IES.</p><p>Para o reitor, o detalhamento pode ser feito por instituição, campus ou conjunto de cursos. Preserve o mesmo período, os critérios de rateio e a base de arrendamentos. Resultados mensais não são convertidos automaticamente em anuais.</p></details>`;
 const form=el.querySelector('#ebitda-form'),readValues=()=>{const f=new FormData(form),p=Object.fromEntries(f);p.education_enabled=f.has('education_enabled');p.education=Object.fromEntries([...educationGroups.flatMap(g=>g.keys.map(([k])=>k)),'other_result','reconciliation'].map(k=>[k,f.get('edu_'+k)]));return p;};
 const toggle=()=>{const on=form.elements.education_enabled.checked;el.querySelector('#education-detail').hidden=!on;el.querySelectorAll('#education-detail input,#education-detail textarea').forEach(i=>i.disabled=!on);};
 const preview=()=>{const box=el.querySelector('#ebitda-preview');try{const p=readValues(),body=normalizeEbitda({...p,scope:p.scope||'Prévia sem abrangência definida',evidence_location:p.evidence_location||'Localização pendente'}),r=calculateEbitda(body);box.innerHTML=`<strong>EBITDA pela DRE: ${money(r.ebitda)}</strong><p>Margem EBITDA: <b>${percent(r.margin_percent)}</b> · Período: ${r.period_months===null?'datas parciais':r.period_months+' meses'}</p>${r.education?`<p>Resultado pelo detalhamento: ${money(r.education.ebitda)} · Diferença para o EBITDA da DRE: <b>${money(r.education.difference)}</b> · Receita líquida: diferença de ${money(r.education.revenue_difference)}.</p><p>${r.education.reconciled?'✓ O detalhamento fecha com os valores informados na DRE.':'Confira as contas: o detalhamento ainda não fecha com a DRE.'}</p><p>Folha / receita líquida: ${percent(r.education.payroll_percent)} · Bolsas e descontos / receita bruta: ${percent(r.education.discount_percent)} · Perdas de recebíveis / receita líquida: ${percent(r.education.bad_debt_percent)}.</p>`:''}${r.revenue_per_student_month!==null?`<p>Receita líquida por aluno/mês: ${money(r.revenue_per_student_month)} · EBITDA por aluno/mês: ${money(r.ebitda_per_student_month)}.</p>`:''}<ul>${r.warnings.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><small>Prévia automática dos valores digitados. Salve com a DRE para registrar a memória.</small>`;}catch(e){box.textContent='O resultado aparecerá ao completar os campos: '+e.message;}};
 toggle();preview();form.addEventListener('input',preview);form.elements.education_enabled.addEventListener('change',()=>{toggle();preview();});form.addEventListener('change',preview);
 bind('ebitda-form','submit',async e=>{e.preventDefault();const p=readValues(),file=form.elements.dre_file.files[0];normalizeEbitda(p);if(!file&&!p.evidence_document_id)throw new Error('Anexe a DRE ou selecione uma já enviada.');const previous=w.ebitda?.calculation_hash||null;if(file)p.evidence_document_id=await storeEvidence(file,'FIN');delete p.dre_file;const current=file?await request('/workflow/'+matter.id):w;p.basis_hash=current.basis_hash;p.previous_calculation_hash=previous;await workflowSave('ebitda',p);});
 bind('ebitda-dre-download','click',()=>downloadEvidence(c.evidence.id));bind('ebitda-memory','click',()=>downloadReport(ebitdaText(c),'text/plain;charset=utf-8',matter.code+'-memoria-ebitda.txt'));bind('ebitda-to-price','click',()=>{tab='valuation';renderMatter();});
}
function renderValuation(el){
 const w=workflowData,b=w.valuation?.body||{},r=w.valuation?.result,money=n=>n===null||n===undefined?'Não calculável':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
 if(!w.lead){el.innerHTML='<p>A análise do preço é restrita ao responsável pelo mandato.</p>';return;}
 const field=(k,label,{type='text',placeholder='',signed=false}={})=>`<label>${label}<input name="${k}" type="${type}" ${type==='number'?`step="0.01" ${signed?'':'min="0"'}`:''} value="${esc(b[k]??'')}" placeholder="${esc(placeholder)}" required></label>`;
 const area=(k,label,placeholder='')=>`<label>${label}<textarea name="${k}" minlength="15" required placeholder="${esc(placeholder)}">${esc(b[k])}</textarea></label>`;
 const proofOptions=id=>'<option value="">Selecione uma evidência vinculada a um requisito</option>'+w.links.map(l=>{const s=w.states.find(s=>s.id===l.state_id),q=w.requirements.find(q=>q.id===s?.requirement_id),d=w.documents.find(d=>d.id===l.document_id),check=w.checks.find(c=>c.link_id===l.id);return `<option value="${l.id}" ${id===l.id?'selected':''}>${esc(q?.code+' · '+d?.file_name+' · '+(check?.body.result==='sufficient'?'conferida':'conferência pendente'))}</option>`;}).join('');
 el.innerHTML=`${regulatorySummary()}<h2>O preço pedido faz sentido?</h2><p>Informe os números, indique de onde vieram e escolha o efeito de cada risco. O módulo calcula uma faixa e mostra o que ainda precisa ser comprovado. Não há IA paga nem consulta automática de preços de mercado.</p>${r?`<div class="form-guide"><strong>${esc(r.conclusion)}</strong><p>Faixa das quotas (100%): <b>${money(r.equity_low)} a ${money(r.equity_high)}</b><br>Preço equivalente pedido (100%): ${money(r.asking_equity)} · Múltiplo implícito: ${r.implied_multiple===null?'Não calculável':r.implied_multiple.toFixed(2)+'x'}<br>Excesso sobre o topo da faixa: ${money(r.gap_above_high)}</p><details><summary>Ver cálculo, sensibilidade e pendências</summary><p>EBITDA ajustado ${money(r.normalized_ebitda)} · Dívida líquida ${money(r.net_debt)} · Ajuste de giro ${money(r.wc_delta)} · Deduções ${money(r.deductions)} · Escrow ${money(r.escrow)} (garantia, sem desconto automático).</p><ul>${r.sensitivity.map(s=>`<li>${s.multiple.toFixed(2)}x → ${money(s.equity)}</li>`).join('')}${r.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></details></div>`:'<div class="form-guide">Sem preço e fontes não é possível concluir se a aquisição está cara ou barata. Você pode salvar premissas ainda não comprovadas; elas ficarão identificadas como condicionais.</div>'}<form id="valuation-form"><input type="hidden" name="ebitda_calculation_hash" value="${esc(b.ebitda_calculation_hash||'')}">
 <fieldset class="evidence-fields"><legend>1. O que o vendedor está pedindo?</legend><div class="form-grid">${field('asking_price','Preço pedido (R$)',{type:'number'})}${field('stake','Participação comprada (%)',{type:'number'})}</div><label>Esse preço corresponde a quê?<select name="quote_type">${options({equity:'Quotas/ações: valor pago aos sócios',enterprise:'Operação inteira: antes de descontar dívida líquida'},b.quote_type)}</select></label><div class="form-grid">${field('date','Data da análise',{type:'date'})}${field('period','Período dos números', {placeholder:'Ex.: janeiro a dezembro de 2025'})}${field('period_months','Quantos meses esses números abrangem?',{type:'number'})}</div>${area('perimeter','Quais empresas, unidades e ativos estão nesse preço?')}${area('payment_terms','Como será pago?','À vista, parcelas, reajustes, earn-out e retenções. O cálculo usa preço nominal; não calcula valor presente das parcelas.')}</fieldset>
 <fieldset class="evidence-fields"><legend>2. Quanto a instituição gera de resultado?</legend>${w.ebitda?`<div class="simple-help"><p>EBITDA salvo na calculadora: <b>${money(w.ebitda.result.ebitda)}</b>, de ${esc(w.ebitda.body.start)} a ${esc(w.ebitda.body.end)}.</p><button id="use-calculated-ebitda" type="button" class="secondary" ${w.ebitda.result.period_months===null?'disabled':''}>Usar o EBITDA e a DRE da calculadora</button><p id="calculated-ebitda-status" class="fine">${b.ebitda_calculation_hash?'Este registro faz referência à memória de cálculo salva.':'O resultado só será aplicado se você clicar no botão.'}</p></div>`:'<p>Você pode calcular o resultado na aba Calcular EBITDA e anexar a DRE.</p>'}<div class="form-grid">${field('revenue','Receita no período (R$)',{type:'number'})}${field('ebitda','Resultado operacional antes de juros, impostos e depreciação — EBITDA (R$)',{type:'number',signed:true})}</div><label>Os números são realizados ou uma previsão?<select name="earnings_type">${options({historical:'Realizados: precisam de documentação',projection:'Previsão/projeção: conclusão condicional'},b.earnings_type)}</select></label><p>Corrija despesas ou receitas excepcionais com ajustes separados. Não exclua custos que continuarão após a compra. Valores negativos reduzem o resultado.</p><div id="price-adjustments"></div><button type="button" id="add-price-adjustment" class="secondary">+ Explicar ajuste do resultado</button></fieldset>
 <fieldset class="evidence-fields"><legend>3. Caixa, dívidas e dinheiro para operar</legend><div class="form-grid">${field('cash','Caixa disponível ao comprador (R$)',{type:'number'})}${field('debt','Dívida financeira (R$)',{type:'number'})}${field('wc_target','Capital de giro necessário/acordado (R$)',{type:'number',signed:true})}${field('wc_delivered','Capital de giro entregue, já ajustado (R$)',{type:'number',signed:true})}</div>${area('cash_debt_basis','O que entrou no caixa e na dívida?','Exclua caixa restrito; explique passivos financeiros. Passivos dos eventos abaixo entram separadamente como dívida adicional.')}${area('wc_basis','Como calculou o capital de giro?','Informe contas incluídas, data-base e provisões. Se uma perda já reduziu o giro ou resultado, não desconte novamente sem demonstrar efeitos distintos.')}</fieldset>
 <fieldset class="evidence-fields"><legend>4. Qual faixa de valor será usada?</legend><p>Valor da operação = EBITDA ajustado × múltiplo. Valor das quotas = operação − dívida líquida + diferença de giro − deduções. Nenhum múltiplo vem preenchido como preço de mercado.</p><div class="form-grid">${field('multiple_low','Múltiplo mínimo',{type:'number'})}${field('multiple_high','Múltiplo máximo',{type:'number'})}</div><label>De onde veio a faixa?<select name="multiple_basis">${options({assumption:'Premissa para simulação: mercado não comprovado',documented:'Fontes documentadas: comparar pelo menos duas'},b.multiple_basis)}</select></label>${area('multiple_reason','Por que essa faixa serve para esta aquisição?','Compare data, porte, cursos, modalidade, margem, crescimento e conceito de dívida. Uma fonte sem comparabilidade não comprova mercado.')}</fieldset>
 <fieldset class="evidence-fields"><legend>5. Qual o efeito de cada risco no preço?</legend><p>Cada evento recebe um único tratamento. Escrow é garantia dentro do preço, sem desconto automático. Se o mesmo assunto tiver efeitos distintos, explique e documente cada parcela em eventos separados.</p>${w.events.map(e=>{const t=b.treatments?.find(t=>t.event_id===e.id)||{};return `<details data-price-event="${e.id}" class="simple-help"><summary>${esc(e.body.title)} ${e.body.resolved?'· encerrado':''}</summary><label>Como considerar?<select data-key="treatment">${options({unquantified:'Ainda não quantificado',debt_like:'Dívida adicional: reduz valor das quotas',deduction:'Dedução adicional negociada',in_earnings:'Já considerado no resultado',in_wc:'Já considerado no capital de giro',escrow:'Escrow/retenção: garantia, não desconto',no_adjustment:'Sem ajuste: justificar'},t.treatment||'unquantified')}</select></label><label>Valor considerado (R$, zero se não quantificado)<input data-key="amount" type="number" min="0" step="0.01" value="${esc(t.amount??0)}" required></label><label>Fonte, cálculo e por que não há dupla contagem<textarea data-key="reason" minlength="15" required>${esc(t.reason)}</textarea></label></details>`;}).join('')||'<p>Nenhum evento registrado.</p>'}</fieldset>
 <fieldset class="evidence-fields"><legend>6. Quais documentos sustentam os valores?</legend><p>Selecione evidências já vinculadas aos requisitos. Confira os arquivos em “Análise das evidências”. Oferta, resultados e balanço são necessários; a faixa documentada exige duas fontes distintas.</p><div id="price-sources"></div><button type="button" id="add-price-source" class="secondary">+ Vincular fonte</button></fieldset>
 ${area('limitations','O que falta confirmar ou não foi possível avaliar?','Indique também auditoria, investimentos futuros, continuidade de cursos, diferenças de período e limitações do método.')}${area('review_note','Conclusão do responsável sobre o preço e a negociação','Explique se o valor pedido é justificável, o que precisa mudar e quais condições dependem de documentos.')}<label class="check"><input name="reviewed" type="checkbox" ${b.reviewed?'checked':''}> Conferi os números, as fontes e o tratamento dos riscos. Esta declaração não aprova a aquisição.</label><button class="primary">Salvar e calcular análise do preço</button></form><hr><h2>Preparado para o futuro agente de IA</h2><p>Baixe a base estruturada com os 305 requisitos, provas, riscos, números e instruções. O arquivo contém dados confidenciais do mandato. O futuro agente deverá citar as fontes e apresentar uma proposta para revisão; não poderá aprovar o parecer. Nenhum dado é enviado ao baixar.</p><button id="download-agent-briefing" class="secondary">Baixar base para futura análise por IA</button>`;
 bind('use-regulatory-reference','click',()=>{const f=el.querySelector('#valuation-form'),r=workflowData.regulatory;if(r)f.elements.limitations.value=(f.elements.limitations.value+'\n'+regulatoryReference(r)).trim();});
 const addSource=s=>{const row=document.createElement('fieldset');row.className='evidence-fields';row.dataset.priceSource='';row.innerHTML=`<label>O que essa fonte comprova?<select data-key="kind">${options({offer:'Preço pedido/oferta',earnings:'Receita e resultado',balance:'Caixa, dívida e giro',multiple:'Referência para múltiplo'},s.kind)}</select></label><label>Evidência<select data-key="link_id" required>${proofOptions(s.link_id)}</select></label><label>Onde está o número e como ele foi utilizado?<textarea data-key="note" minlength="15" required>${esc(s.note)}</textarea></label><button type="button" class="text-btn">Remover fonte</button>`;row.querySelector('button').onclick=()=>row.remove();document.querySelector('#price-sources').append(row);};
 const addAdjustment=a=>{const row=document.createElement('fieldset');row.className='evidence-fields';row.dataset.priceAdjustment='';row.innerHTML=`<label>Valor a somar ou subtrair do EBITDA (R$)<input data-key="amount" type="number" step="0.01" value="${esc(a.amount??'')}" required></label><label>Motivo e cálculo<textarea data-key="reason" minlength="15" required>${esc(a.reason)}</textarea></label><label>Evidência<select data-key="link_id" required>${proofOptions(a.link_id)}</select></label><button type="button" class="text-btn">Remover ajuste</button>`;row.querySelector('button').onclick=()=>row.remove();document.querySelector('#price-adjustments').append(row);};
 (b.sources?.length?b.sources:[{kind:'offer'},{kind:'earnings'},{kind:'balance'}]).forEach(addSource);(b.adjustments||[]).forEach(addAdjustment);
 bind('add-price-source','click',()=>addSource({kind:'multiple'}));bind('add-price-adjustment','click',()=>addAdjustment({}));
 bind('valuation-form','submit',async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget)),rows=selector=>Array.from(el.querySelectorAll(selector)).map(row=>Object.fromEntries(Array.from(row.querySelectorAll('[data-key]')).map(i=>[i.dataset.key,i.value])));p.context_hash=w.economic_context_hash;p.reviewed=e.currentTarget.elements.reviewed.checked;p.sources=rows('[data-price-source]');p.adjustments=rows('[data-price-adjustment]');p.treatments=Array.from(el.querySelectorAll('[data-price-event]')).map(row=>({event_id:row.dataset.priceEvent,...Object.fromEntries(Array.from(row.querySelectorAll('[data-key]')).map(i=>[i.dataset.key,i.value]))}));await workflowSave('valuation',p);});
 bind('use-calculated-ebitda','click',()=>{const c=w.ebitda,f=el.querySelector('#valuation-form');if(!c||c.result.period_months===null)return;f.elements.ebitda.value=c.result.ebitda;f.elements.revenue.value=c.body.net_revenue;f.elements.period.value=c.body.start+' a '+c.body.end;f.elements.period_months.value=c.result.period_months;f.elements.earnings_type.value=c.body.basis;f.elements.ebitda_calculation_hash.value=c.calculation_hash;let row=Array.from(el.querySelectorAll('[data-price-source]')).find(row=>row.querySelector('[data-key=kind]').value==='earnings');if(!row){addSource({kind:'earnings'});row=el.querySelector('[data-price-source]:last-child');}row.querySelector('[data-key=link_id]').value=c.link_id;row.querySelector('[data-key=note]').value='DRE e memória de cálculo: '+c.body.evidence_location+'; abrangência '+c.body.scope+'; período '+c.body.start+' a '+c.body.end+'. Conferir a evidência no fluxo de análise.';el.querySelector('#calculated-ebitda-status').textContent='Cálculo aplicado aos campos. Revise os ajustes de EBITDA abaixo para não repetir despesas ou provisões já incluídas na DRE. Salve a análise de preço para registrar.';});
 for(const key of ['ebitda','revenue','period','period_months','earnings_type'])el.querySelector('#valuation-form').elements[key].addEventListener('input',()=>{el.querySelector('#valuation-form').elements.ebitda_calculation_hash.value='';const status=el.querySelector('#calculated-ebitda-status');if(status)status.textContent='Valores editados manualmente: a referência automática ao cálculo foi removida.';});
 bind('download-agent-briefing','click',async()=>downloadReport(JSON.stringify(await request('/workflow/'+matter.id+'/briefing'),null,2),'application/json',matter.code+'-base-agente-confidencial.json'));
}
function evidenceForm(linkId){
 const w=workflowData,l=w.links.find(l=>l.id===linkId),d=documents.find(d=>d.id===l.document_id),b=w.checks.find(c=>c.link_id===linkId)?.body||{};
 modal('Conferir evidência — '+d.file_name,`<p class="fine">Hash registrado: ${esc(d.sha256)}. A conferência abaixo é feita pelo analista; a presença do arquivo não valida seu conteúdo.</p><form id="evidence-review"><div class="form-grid"><label>Origem/emissor<input name="origin" value="${esc(b.origin)}" required></label><label>Período ou data abrangida<input name="period" value="${esc(b.period)}" required></label></div><div class="form-grid"><label>Entidade/unidade abrangida<input name="unit" value="${esc(b.unit)}" required></label><label>Versão ou data de obtenção<input name="version" value="${esc(b.version)}" required></label></div><label>Página, aba, linha ou seção examinada<input name="location" value="${esc(b.location||l.evidence_location)}" required></label><label>Autenticidade/assinatura<select name="signature">${options({unverified:'Ainda não verificada',verified:'Conferida pelo analista',not_applicable:'Assinatura não aplicável à fonte — explicar como foi conferida'},b.signature||'unverified')}</select></label><label>Como foi conferida?<textarea name="method" minlength="15" required>${esc(b.method)}</textarea></label><label>O que o arquivo comprova e quais são os limites?<textarea name="coverage" minlength="10" required>${esc(b.coverage)}</textarea></label><label>Resultado<select name="result">${options({partial:'Parcial ou com limitação',sufficient:'Suficiente para a afirmação examinada',rejected:'Não serve como prova para este item'},b.result||'partial')}</select></label><label>Observações<textarea name="note">${esc(b.note)}</textarea></label>${w.writable?'<button class="primary">Salvar conferência</button>':''}</form>`,()=>bind('evidence-review','submit',async e=>{e.preventDefault();await workflowSave('evidence',{link_id:linkId,...Object.fromEntries(new FormData(e.currentTarget))});}));
 if(!w.writable)document.querySelectorAll('#evidence-review input,#evidence-review textarea,#evidence-review select').forEach(i=>i.disabled=true);
}
function reviewForm(stateId){
 const w=workflowData,s=states.find(s=>s.id===stateId),r=requirements.find(r=>r.id===s.requirement_id),effective=w.effective.find(e=>e.state_id===stateId),b=effective.previous_review?.body||{},links=w.links.filter(l=>l.state_id===stateId);
 modal(r.code+' — Análise do responsável/analista',`<h3>${esc(r.question)}</h3>${b.simulation?'<p class="notice-inline">Esta análise foi preparada como revisão simulada do cenário fictício. Não foi realizada pessoalmente pelo titular.</p>':''}<p><strong>Resposta declarada:</strong> ${esc(s.answer||'Não fornecida')}</p><p class="fine">${esc(r.applicability)}</p>${effective.previous_review&&!effective.valid?'<p class="notice-inline">A base mudou. A análise anterior foi preservada, mas precisa ser refeita e confirmada.</p>':''}<details><summary>Critérios e referências de pesquisa</summary><ul>${(r.review_checks||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${(r.sources||[]).map(id=>{const source=w.revision.sources[id];return source?.url?`<p><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)}</a></p>`:`<p>${esc(source?.title)}</p>`;}).join('')}<p class="fine">O analista confirma a versão e a aplicabilidade da regra na data-base. O cadastro de referências não faz validação jurídica automática.</p></details><h3>Evidências vinculadas</h3>${links.map(l=>{const d=documents.find(d=>d.id===l.document_id),c=w.checks.find(c=>c.link_id===l.id);return `<div class="linked-evidence"><div><strong>${esc(d.file_name)}</strong><p class="fine">${esc(c?{sufficient:'Conferida como suficiente',partial:'Conferência parcial',rejected:'Não aceita como prova'}[c.body.result]:'Ainda não conferida')}</p></div><button class="secondary" data-quality="${l.id}">Conferir arquivo</button></div>`;}).join('')||'<p>Sem arquivos vinculados. Volte ao preenchimento para anexar ou vincular uma evidência.</p>'}${r.columns?.length?`<button id="structured-open" class="secondary">Abrir tabela de ${esc(r.table_family)} (${s.structured_rows?.length||0} linhas)</button>`:''}<form id="requirement-review"><label>Conclusão<select name="decision">${options({verified:'Conforme após revisão das evidências',qualified:'Com ressalva',noncompliant:'Não conforme',not_applicable:'Não aplicável — justificar',not_verified:'Não verificado — registrar limitação'},b.decision||'not_verified')}</select></label><label>Análise e justificativa<textarea name="analysis" minlength="30" rows="5" required>${esc(b.analysis)}</textarea></label><label>Critério ou regra aplicável, versão e data<textarea name="rule" minlength="15" required>${esc(b.rule)}</textarea></label><label>Limitações da análise<textarea name="limitations" minlength="5" required>${esc(b.limitations)}</textarea></label><label>Risco, quando houver ressalva ou não conformidade<select name="risk">${options({amber:'Amarelo',red:'Vermelho'},b.risk||'amber')}</select></label><label>Justificativa do risco (impacto, probabilidade e urgência)<textarea name="risk_reason">${esc(b.risk_reason)}</textarea></label><h3>Quais evidências sustentam esta conclusão?</h3>${links.map(l=>{const d=documents.find(d=>d.id===l.document_id),c=w.checks.find(c=>c.link_id===l.id);return `<label class="check"><input type="checkbox" name="proofs" value="${l.id}" ${b.proofs?.some(p=>p.link_id===l.id)?'checked':''} ${c?.body.result==='sufficient'?'':'disabled'}> ${esc(d.file_name)} ${c?.body.result==='sufficient'?'':'— confira a suficiência antes de selecionar'}</label>`;}).join('')}<p class="fine">Não aplicável e não verificado não recebem cor verde. Ressalvas, não conformidades e limitações precisam de evento e providência antes da aprovação final.</p>${w.writable?'<button class="primary">Salvar análise pessoal</button>':''}</form>`);
 document.querySelectorAll('[data-quality]').forEach(btn=>btn.onclick=()=>evidenceForm(btn.dataset.quality));bind('structured-open','click',()=>structuredForm(stateId));
 bind('requirement-review','submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget);await workflowSave('review',{state_id:stateId,basis_hash:effective.basis_hash,...Object.fromEntries(data),proofs:data.getAll('proofs')});});
 if(!w.writable)document.querySelectorAll('#requirement-review input,#requirement-review textarea,#requirement-review select').forEach(i=>i.disabled=true);
}
function parseCsv(input){
 const delimiter=input.split(/\r?\n/,1)[0].includes(';')?';':',',rows=[];let row=[],cell='',quoted=false;
 for(let i=0;i<input.length;i++){const ch=input[i];if(ch==='"'){if(quoted&&input[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===delimiter&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&input[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}
 if(quoted)throw new Error('A planilha CSV contém aspas sem fechamento.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;
}
function structuredForm(stateId){
 const s=states.find(s=>s.id===stateId),r=requirements.find(r=>r.id===s.requirement_id);let rows=structuredClone(s.structured_rows||[]);
 const show=()=>{
  modal(r.code+' — Tabela de informações',`<p>Uma linha por registro. Use códigos internos e não inclua CPF, senhas ou dados desnecessários. O CSV pode ser aberto no Excel; mantenha as colunas da ficha.</p><div class="toolbar"><button id="table-template" class="secondary">Baixar planilha vazia (CSV) ↓</button><label>Importar CSV<input id="table-import" type="file" accept=".csv"></label><button id="table-add" class="secondary">+ Adicionar linha</button></div><div class="table-scroll"><table class="demo-table"><thead><tr>${r.columns.map(c=>`<th>${esc(c)}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map((row,i)=>`<tr>${r.columns.map((c,j)=>`<td><input data-row="${i}" data-col="${j}" value="${esc(row[j])}" aria-label="${esc(c)} linha ${i+1}"></td>`).join('')}<td><button data-remove-row="${i}" class="text-btn">Remover</button></td></tr>`).join('')}</tbody></table></div><p class="fine">${rows.length} linhas. A importação preserva o arquivo de origem no cofre; confira abrangência e documentos citados na análise.</p><button id="table-save" class="primary">Salvar tabela</button>`);
  document.querySelectorAll('[data-row]').forEach(i=>i.oninput=()=>rows[Number(i.dataset.row)][Number(i.dataset.col)]=i.value);
  document.querySelectorAll('[data-remove-row]').forEach(b=>b.onclick=()=>{rows.splice(Number(b.dataset.removeRow),1);show();});
  bind('table-add','click',()=>{if(rows.length>=1000)throw new Error('Limite de mil linhas.');rows.push(r.columns.map(()=>''));show();});
  bind('table-template','click',()=>downloadReport('\ufeff'+r.columns.join(';')+'\r\n','text/csv;charset=utf-8',r.code+'-tabela.csv'));
  bind('table-import','change',async e=>{const file=e.currentTarget.files[0];if(!file)return;if(file.size>1024*1024)throw new Error('Use CSV de até 1 MB e mil linhas.');const parsed=parseCsv((await file.text()).replace(/^\ufeff/,''));if(!parsed.length||parsed[0].some((h,i)=>h.trim()!==r.columns[i])||parsed[0].length!==r.columns.length)throw new Error('Use exatamente as colunas da planilha vazia.');const imported=parsed.slice(1);if(imported.length>1000||imported.some(row=>row.length!==r.columns.length))throw new Error('Confira a quantidade de colunas e o limite de mil linhas.');const id=await storeEvidence(file,r.front);await rpc('dd_save_response',{m:matter.id,r:r.id,a:s.answer||'Informações individualizadas na tabela e no arquivo CSV anexado; aguardam conferência.',attachments:[{document_id:id,location:'Tabela CSV, linha 1 de cabeçalho e registros seguintes',template_id:null}]});rows=imported;show();});
  bind('table-save','click',()=>workflowSave('table',{state_id:stateId,rows}));
 };show();
}
function renderWorkflowEvents(el){
 const w=workflowData;
 el.innerHTML=`<div class="section-heading"><h2>Riscos, valores e providências</h2>${w.writable?'<button id="workflow-event-new" class="primary">+ Registrar evento</button>':''}</div><p>Um problema pode afetar vários requisitos. Use o mesmo evento para evitar duplicidade. Valores são separados em dívida, perda estimada, investimento e ajuste de preço; não há desconto global automático.</p>${w.events.map(e=>`<article class="finding"><span class="severity ${e.body.risk}">${esc(e.body.risk==='red'?'Vermelho':'Amarelo')}</span><div><h3>${esc(e.body.title)}</h3><p>${esc(e.body.issue)}</p><p>${esc(e.body.action||'Complete a providência')} · ${esc(e.body.owner||'Sem responsável')} · ${esc(e.body.due_date||'Sem prazo')}</p><p>${e.body.resolved?'Encerrado pelo responsável':e.body.closing_block?'Bloqueia o fechamento':'Pendente de tratamento'} ${e.body.migration_pending?'· achado anterior: completar análise':''}</p></div><button class="secondary" data-event-edit="${e.id}">Abrir evento</button></article>`).join('')||'<p>Nenhum evento registrado.</p>'}${w.legacy.filter(f=>!w.events.some(e=>e.body.legacy_id===f.id)).map(f=>`<p class="notice-inline">Achado anterior ${esc(f.code)} precisa de evento: <button class="text-btn" data-event-legacy="${f.id}">Completar tratamento</button></p>`).join('')}`;
 bind('workflow-event-new','click',()=>eventForm());document.querySelectorAll('[data-event-edit]').forEach(b=>b.onclick=()=>eventForm(b.dataset.eventEdit));document.querySelectorAll('[data-event-legacy]').forEach(b=>b.onclick=()=>eventForm(null,b.dataset.eventLegacy));
}
function eventForm(id=null,legacyId=null){
 const w=workflowData,old=id?w.events.find(e=>e.id===id):null,legacy=legacyId?w.legacy.find(f=>f.id===legacyId):null,b=old?.body|| (legacy?{legacy_id:legacy.id,title:legacy.title,issue:legacy.description,consequence:legacy.consequence,requirement_ids:[legacy.requirement_id],risk:legacy.severity,amount:legacy.value_brl,mechanism:mechanisms[legacy.mechanism]}:{});
 modal('Evento e providência',`<form id="event-form"><label>Nome do problema<input name="title" value="${esc(b.title)}" required></label><label>Requisitos afetados<select name="requirements" multiple size="8">${requirements.map(r=>`<option value="${r.id}" ${b.requirement_ids?.includes(r.id)?'selected':''}>${esc(r.code+' — '+r.question)}</option>`).join('')}</select></label><label>O que foi constatado?<textarea name="issue" minlength="15" required>${esc(b.issue)}</textarea></label><label>Consequência para a compra<textarea name="consequence" minlength="15" required>${esc(b.consequence)}</textarea></label><div class="form-grid"><label>Risco<select name="risk">${options({amber:'Amarelo',red:'Vermelho'},b.risk||'amber')}</select></label><label>Probabilidade<select name="probability">${options({unknown:'Ainda não estimada',low:'Baixa',medium:'Média',high:'Alta'},b.probability||'unknown')}</select></label></div><label>Por que este risco é relevante? (impacto e urgência)<textarea name="risk_reason" minlength="15" required>${esc(b.risk_reason)}</textarea></label><div class="form-grid"><label>Natureza do valor<select name="nature">${options({unknown:'Não quantificado / a conferir',debt:'Dívida já existente',loss_estimate:'Estimativa de perda',capex:'Investimento ou correção',price_adjustment:'Ajuste proposto de preço'},b.nature||'unknown')}</select></label><label>Valor (R$, quando disponível)<input name="amount" type="number" min="0" step="0.01" value="${esc(b.amount)}"></label></div><label>De onde vem o valor e como foi calculado? Evite contar o mesmo custo duas vezes.<textarea name="value_basis">${esc(b.value_basis)}</textarea></label><label>Quando pode ocorrer o efeito?<input name="timing" value="${esc(b.timing)}"></label><label>O que será feito?<textarea name="action" minlength="10" required>${esc(b.action)}</textarea></label><label>Proteção sugerida no contrato<textarea name="mechanism" minlength="10" required>${esc(b.mechanism)}</textarea></label><div class="form-grid"><label>Responsável pela providência<input name="owner" value="${esc(b.owner)}" required></label><label>Prazo<input name="due_date" type="date" value="${esc(b.due_date)}" required></label></div><label>Como comprovar a solução?<textarea name="closure_criteria" minlength="10" required>${esc(b.closure_criteria)}</textarea></label><h3>Evidências do evento</h3>${w.links.map(l=>{const d=documents.find(d=>d.id===l.document_id),s=states.find(s=>s.id===l.state_id),r=requirements.find(r=>r.id===s.requirement_id);return `<label class="check"><input type="checkbox" name="proofs" value="${l.id}" ${b.proofs?.includes(l.id)?'checked':''}> ${esc(r.code+' — '+d.file_name)}</label>`;}).join('')||'<p>Primeiro vincule um arquivo ao requisito no preenchimento.</p>'}<label class="check"><input name="closing_block" type="checkbox" ${b.closing_block?'checked':''}> Este evento impede fechar a aquisição enquanto estiver aberto.</label>${w.lead?`<label class="check"><input name="resolved" type="checkbox" ${b.resolved?'checked':''}> Conferi a solução e encerro este evento.</label><label>Comprovação do encerramento<textarea name="resolution">${esc(b.resolution)}</textarea></label>`:''}${w.writable?'<button class="primary">Salvar evento e providência</button>':''}</form>`,()=>bind('event-form','submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await workflowSave('event',{...Object.fromEntries(f),id,legacy_id:b.legacy_id||null,requirement_ids:f.getAll('requirements'),proofs:f.getAll('proofs'),closing_block:f.has('closing_block'),resolved:f.has('resolved')});}));
 if(!w.writable)document.querySelectorAll('#event-form input,#event-form textarea,#event-form select').forEach(i=>i.disabled=true);
}
async function opinionView(id){
 const target=matter.id;const report=await request('/workflow/'+target+'/report/'+id),a=report.approval;if(matter?.id!==target)return;
 const banner=(report.approved?'APROVADO PELO RESPONSÁVEL':'RASCUNHO — SEM APROVAÇÃO FINAL')+(report.current?' — BASE ATUAL':' — BASE ALTERADA; VERSÃO HISTÓRICA');
 const approval=a?`\n\nREGISTRO DE APROVAÇÃO\n${a.body.name} — ${a.body.registration}\nConta: ${a.body.authenticated_email||a.approved_by}\nData: ${a.approved_at}\nDeclaração: ${a.body.note}\nHash do texto aprovado: ${a.body.report_hash}\nBase aprovada: ${a.body.basis_hash}\n${a.body.authentication}`:'';
 modal('Parecer — '+banner,`<p><strong>${esc(banner)}</strong></p><p class="fine">A versão identifica os arquivos, hashes, páginas/abas e análises examinadas. Uma aprovação anterior não se estende a uma base alterada.</p><div class="toolbar"><button id="opinion-download-text" class="secondary">Baixar texto ↓</button><button id="opinion-download-html" class="secondary">Baixar versão para imprimir em PDF ↓</button><button id="opinion-download-json" class="text-btn">Baixar base de rastreabilidade ↓</button></div><pre class="agent-prompt">${esc(report.text+approval)}</pre>`);
 bind('opinion-download-text','click',()=>downloadReport(banner+'\n\n'+report.text+approval,'text/plain;charset=utf-8',matter.code+'-parecer-'+id+'.txt'));
 bind('opinion-download-json','click',()=>downloadReport(JSON.stringify(report,null,2),'application/json',matter.code+'-parecer-'+id+'.json'));
 bind('opinion-download-html','click',()=>downloadReport(`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Parecer ${esc(matter.code)}</title><style>body{max-width:900px;margin:40px auto;font:15px/1.6 Arial;color:#111}pre{white-space:pre-wrap;font:inherit;overflow-wrap:anywhere}h1{font-size:22px}@media print{body{margin:0}h1{font-size:18px}}</style><h1>${esc(banner)}</h1><p>Use Imprimir no navegador e selecione Salvar como PDF.</p><pre>${esc(report.text+approval)}</pre></html>`,'text/html;charset=utf-8',matter.code+'-parecer-'+id+'.html'));
}
